r=f.add_run(); b=OxmlElement('w:fldChar'); b.set(qn('w:fldCharType'),'begin'); i=OxmlElement('w:instrText'); i.text='PAGE'; z=OxmlElement('w:fldChar'); z.set(qn('w:fldCharType'),'end'); r._r.extend([b,i,z])
def para(t='',align=None):
 p=d.add_paragraph(); p.alignment=align if align is not None else WD_ALIGN_PARAGRAPH.JUSTIFY; p.add_run(t); return p
