def table(headers,rows):
 t=d.add_table(rows=1,cols=len(headers)); t.style='Table Grid'; t.alignment=WD_TABLE_ALIGNMENT.CENTER
 for j,x in enumerate(headers):
  c=t.rows[0].cells[j]; c.text=x; c.vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.CENTER
  sh=OxmlElement('w:shd'); sh.set(qn('w:fill'),'DDEBDD'); c._tc.get_or_add_tcPr().append(sh)
  for r in c.paragraphs[0].runs: r.bold=True
 for row in rows:
  cells=t.add_row().cells
  for j,x in enumerate(row): cells[j].text=str(x)
 for row in t.rows:
  for c in row.cells:
   for p in c.paragraphs:
    p.paragraph_format.space_after=Pt(1)
    for r in p.runs: r.font.name='Times New Roman'; r.font.size=Pt(9)
 d.add_paragraph(); return t
